export const WP_THEME_FILES: Readonly<Record<string, string>> = {
  "functions.php": "<?php\n// Gaiada WebDesk headless theme (M6-P5a). The WordPress glue: deliberately thin. All logic lives in\n// inc/ and is testable with php-cli alone (webdesk/wordpress/test/*-probe.php).\n//\n// Every front-end request is handed to Router on `template_redirect` and ends there (exit), so\n// content NEVER falls through to WordPress posts/pages. Configuration is read from wp-config.php\n// constants then getenv() — never from the database (see inc/config.php).\ndeclare(strict_types=1);\n\nnamespace GaiadaWebDesk\\Theme;\n\nrequire_once __DIR__ . '/inc/block-vocabulary.php';\nrequire_once __DIR__ . '/inc/block-renderer.php';\nrequire_once __DIR__ . '/inc/config.php';\nrequire_once __DIR__ . '/inc/layout.php';\nrequire_once __DIR__ . '/inc/router.php';\nrequire_once __DIR__ . '/inc/sdk-transport.php';\n\nif (is_admin()) {\n    require_once __DIR__ . '/inc/settings-page.php';\n}\n\nadd_action('template_redirect', __NAMESPACE__ . '\\\\gaiada_webdesk_serve', 0);\n\nfunction gaiada_webdesk_serve(): void\n{\n    // Not \"content\": WordPress's own robots.txt / favicon / feed handlers keep working.\n    if (is_robots() || is_favicon() || is_feed()) {\n        return;\n    }\n\n    $config = Config::fromEnvironment();\n    if ($config->isConfigured()) {\n        $fetch = gaiada_webdesk_sdk_fetcher($config);\n    } else {\n        // Never called: Router answers 503 before it routes when the config has problems.\n        $fetch = static function (): array {\n            throw new UpstreamUnavailable('not configured');\n        };\n    }\n\n    $uriPath = (string) wp_parse_url((string) wp_unslash($_SERVER['REQUEST_URI'] ?? '/'), PHP_URL_PATH);\n    $homePath = rtrim((string) wp_parse_url(home_url('/'), PHP_URL_PATH), '/');\n    if ($homePath !== '' && str_starts_with($uriPath, $homePath)) {\n        $uriPath = substr($uriPath, strlen($homePath));\n    }\n\n    $method = strtoupper((string) ($_SERVER['REQUEST_METHOD'] ?? 'GET'));\n    $result = (new Router($config, $fetch))->handle($method, $uriPath);\n\n    status_header($result['status']);\n    if ($result['status'] !== 200) {\n        nocache_headers();\n    }\n    foreach ($result['headers'] as $name => $value) {\n        header($name . ': ' . $value);\n    }\n    header('Content-Type: text/html; charset=utf-8');\n\n    if ($method !== 'HEAD') {\n        ob_start();\n        wp_head();\n        $head = (string) ob_get_clean();\n        ob_start();\n        wp_footer();\n        $foot = (string) ob_get_clean();\n        echo gaiada_webdesk_document($result['title'], $result['body'], $result['lang'], $head, $foot);\n    }\n    exit;\n}\n",
  "inc/block-renderer.php": "<?php\n// webdesk/wordpress/theme/gaiada-webdesk/inc/block-renderer.php\n//\n// WSK-35 — the PHP-side half of the renderer invariant (webdesk-design.md §05 hard rule 2), and\n// the ticket's most load-bearing correctness requirement: an unknown block type at RENDER time\n// must be SKIPPED AND REPORTED, never rejected and never silently dropped without a trace. This\n// is the OPPOSITE of composition/authoring time (WSK-14's `validateCollectionComposition`, which\n// genuinely REJECTS an out-of-vocabulary block type before it is ever saved) — getting these two\n// moments backwards is documented in WSK-18's own report as \"the easiest mistake available\".\n//\n// Mirrors `webdesk/blocks/src/renderer/resolve-blocks.ts` + `report.ts` (WSK-16, the TS renderer,\n// frozen) exactly, one function per file's job:\n//   - gaiada_resolve_blocks()  == resolve-blocks.ts's resolveBlocks()\n//   - gaiada_report_unknown()  == report.ts's defaultUnknownBlockReport()\n//   - gaiada_render_blocks()  == BlockRenderer.astro's loop\ndeclare(strict_types=1);\n\nnamespace GaiadaWebDesk\\Theme;\n\nrequire_once __DIR__ . '/block-vocabulary.php';\nrequire_once __DIR__ . '/safety.php';\n\n/**\n * Splits a raw `blocks` array (an ItemEnvelope's own `blocks`, per webdesk/delivery/vocabulary/\n * envelope.ts) into resolved entries — never throws, mirroring resolve-blocks.ts's own \"a\n * resolution failure here is exactly the scenario the renderer invariant exists to survive\"\n * comment. Preserves order and the original index (needed for an accurate report).\n *\n * @param array<int,array<string,mixed>> $blocks\n * @return array<int,array{index:int,type:string,props:array<string,mixed>,known:bool}>\n */\nfunction gaiada_resolve_blocks(array $blocks): array\n{\n    $known = gaiada_known_block_types();\n    $resolved = [];\n    foreach (array_values($blocks) as $index => $block) {\n        $type = is_string($block['type'] ?? null) ? $block['type'] : '';\n        $props = is_array($block['props'] ?? null) ? $block['props'] : [];\n        $resolved[] = [\n            'index' => $index,\n            'type' => $type,\n            'props' => $props,\n            'known' => in_array($type, $known, true),\n        ];\n    }\n    return $resolved;\n}\n\n/**\n * The reporting channel — always fires for an unknown block, mirroring report.ts's\n * defaultUnknownBlockReport(): \"a vocabulary-MINOR addition must reach a site pinned to an older\n * renderer as a visible gap, never a crash.\" Logs via error_log (the one channel every PHP host,\n * including Hostinger shared hosting, actually has) AND appends to a process-local collector a\n * host (e.g. an admin notice, a QA probe) can read back — the exact \"console warning plus a\n * reporting hook a host can wire to QA\" shape WSK-16's own ticket text specifies, restated for a\n * request/response runtime that has no persistent in-memory host to hold a callback across\n * requests the way a JS module singleton can.\n *\n * @param array{index:int,type:string} $entry\n */\nfunction gaiada_report_unknown_block(array $entry, string $collection, string $slug): void\n{\n    $where = $collection !== '' ? \" in \\\"{$collection}/{$slug}\\\"\" : '';\n    $message = sprintf(\n        '[gaiada-webdesk] unknown block type \"%s\" at blocks[%d]%s — rendered nothing. ' .\n        'Renderer invariant (webdesk-design.md §05 hard rule 2): a vocabulary-MINOR addition ' .\n        'must reach a site pinned to an older renderer as a visible gap, never a crash.',\n        $entry['type'],\n        $entry['index'],\n        $where,\n    );\n    error_log($message);\n\n    global $gaiada_unknown_block_reports;\n    if (!is_array($gaiada_unknown_block_reports)) {\n        $gaiada_unknown_block_reports = [];\n    }\n    $gaiada_unknown_block_reports[] = [\n        'type' => $entry['type'],\n        'index' => $entry['index'],\n        'collection' => $collection,\n        'slug' => $slug,\n    ];\n}\n\n/** @return array<int,array{type:string,index:int,collection:string,slug:string}> */\nfunction gaiada_drain_unknown_block_reports(): array\n{\n    global $gaiada_unknown_block_reports;\n    $reports = is_array($gaiada_unknown_block_reports) ? $gaiada_unknown_block_reports : [];\n    $gaiada_unknown_block_reports = [];\n    return $reports;\n}\n\n/**\n * Renders every KNOWN block in order and calls `gaiada_report_unknown_block()` (never a render\n * call) for every UNKNOWN one — the renderer invariant, proven by this exact function in this\n * ticket's own render-time probe (see test/render-invariant-probe.php): known blocks before and\n * after an unknown one both still render; the unknown one contributes zero output bytes.\n *\n * @param array<int,array<string,mixed>> $blocks\n */\nfunction gaiada_render_blocks(array $blocks, string $collection = '', string $slug = ''): string\n{\n    $html = '';\n    foreach (gaiada_resolve_blocks($blocks) as $resolved) {\n        if (!$resolved['known']) {\n            gaiada_report_unknown_block($resolved, $collection, $slug);\n            continue; // skip — never render, never throw, never abort the rest of the array.\n        }\n        $html .= gaiada_render_known_block($resolved['type'], $resolved['props']);\n    }\n    return $html;\n}\n\n/** Dispatches to one render function per known block type (inc/block-templates/*.php). A type\n *  that passed gaiada_known_block_types() but has no template function is a THEME bug (vocabulary\n *  and templates out of sync within this repo, not a render-time contract violation) — it throws,\n *  deliberately, so that gap is loud in dev rather than silently rendering nothing like a real\n *  unknown block would (those are two different failure classes and must not look the same).\n *\n * @param array<string,mixed> $props\n */\nfunction gaiada_render_known_block(string $type, array $props): string\n{\n    // Fully-qualified, deliberately: `function_exists()`/`call_user_func()` resolve a BARE string\n    // name against the GLOBAL namespace, never the caller's current namespace (PHP's own\n    // documented behaviour for dynamic name resolution) — `__NAMESPACE__` here is\n    // \"GaiadaWebDesk\\Theme\", matching where block-templates.php actually declares these\n    // functions. Confirmed the hard way: the bare form silently found nothing on a real Linux run.\n    $fn = __NAMESPACE__ . '\\\\gaiada_render_block_' . $type;\n    if (!function_exists($fn)) {\n        throw new \\RuntimeException(\n            \"gaiada_render_blocks: block type \\\"{$type}\\\" is in gaiada_known_block_types() but \" .\n            \"has no {$fn}() template function — the theme's template set is out of sync with the \" .\n            \"vendored vocabulary. Run scripts/vendor-block-vocabulary.mjs and add the missing \" .\n            \"template, or this is a real theme bug, not a render-time contract violation.\"\n        );\n    }\n    return (string) $fn($props);\n}\n\nfunction gaiada_h(mixed $value): string\n{\n    return htmlspecialchars(is_string($value) ? $value : (string) json_encode($value), ENT_QUOTES, 'UTF-8');\n}\n\nrequire_once __DIR__ . '/block-templates.php';\n",
  "inc/block-templates.php": "<?php\n// webdesk/wordpress/theme/gaiada-webdesk/inc/block-templates.php\n//\n// WSK-35 — one render function per KNOWN vocabulary block type (webdesk/blocks/src/components/*\n// .astro, WSK-16, is the frozen reference this file mirrors in PHP). Intentionally simple markup\n// — this ticket's bar is proving the renderer INVARIANT (known blocks render, unknown ones are\n// skipped-and-reported), not shipping a pixel-accurate theme; visual polish is design-system work\n// outside WSK-35's scope. Every function name is `gaiada_render_block_<type>`, matching\n// block-renderer.php's `gaiada_render_known_block()` dispatch by convention.\ndeclare(strict_types=1);\n\nnamespace GaiadaWebDesk\\Theme;\n\n/** An <img> whose src has already passed gaiada_safe_img_src(); an empty (refused) src omits the\n *  attribute. $url is NOT yet escaped here, $alt IS already escaped. $width/$height are emitted only\n *  when they are positive integers (Astro passes media.width/height straight through). */\nfunction gaiada_img_tag(string $url, string $alt, mixed $width = null, mixed $height = null): string\n{\n    $src = $url === '' ? '' : ' src=\"' . gaiada_h($url) . '\"';\n    $dims = '';\n    if (is_int($width) && $width > 0) {\n        $dims .= ' width=\"' . $width . '\"';\n    }\n    if (is_int($height) && $height > 0) {\n        $dims .= ' height=\"' . $height . '\"';\n    }\n    return \"<img{$src} alt=\\\"{$alt}\\\"{$dims} loading=\\\"lazy\\\">\";\n}\n\n/** One vocabulary `media` value ({ url, alt?, width?, height? }) as an <img>. The url passes\n *  gaiada_safe_img_src(), the alt gaiada_h(). */\nfunction gaiada_media_img(mixed $media): string\n{\n    $m = is_array($media) ? $media : [];\n    return gaiada_img_tag(\n        gaiada_safe_img_src($m['url'] ?? ''),\n        gaiada_h($m['alt'] ?? ''),\n        $m['width'] ?? null,\n        $m['height'] ?? null,\n    );\n}\n\n/** A vocabulary `media` value is a non-empty { url } object. */\nfunction gaiada_has_media(mixed $media): bool\n{\n    return is_array($media) && is_string($media['url'] ?? null) && $media['url'] !== '';\n}\n\n/** The inert JSON payload Astro emits for a Lexical `{ root }` document (RichText.astro,\n *  Testimonial.astro): a <script type=\"application/json\"> whose body cannot close the tag. */\nfunction gaiada_json_payload(mixed $value): string\n{\n    return '<script type=\"application/json\">' . gaiada_safe_json_for_script($value) . '</script>';\n}\n\n/** @param array<string,mixed> $props */\nfunction gaiada_render_block_hero(array $props): string\n{\n    $heading = gaiada_h($props['heading'] ?? '');\n    $html = \"<section class=\\\"gaiada-block gaiada-block-hero\\\"><h1>{$heading}</h1>\";\n    if (is_string($props['subheading'] ?? null) && $props['subheading'] !== '') {\n        $html .= '<p>' . gaiada_h($props['subheading']) . '</p>';\n    }\n    if (gaiada_has_media($props['media'] ?? null)) {\n        $html .= gaiada_media_img($props['media']);\n    }\n    $ctaLabel = $props['ctaLabel'] ?? '';\n    $ctaHref = $props['ctaHref'] ?? '';\n    if (is_string($ctaLabel) && $ctaLabel !== '' && is_string($ctaHref) && $ctaHref !== '') {\n        $html .= '<a class=\"gaiada-hero-cta\" href=\"' . gaiada_h(gaiada_safe_href($ctaHref)) . '\">' . gaiada_h($ctaLabel) . '</a>';\n    }\n    return $html . '</section>';\n}\n\n/** @param array<string,mixed> $props */\nfunction gaiada_render_block_richText(array $props): string\n{\n    // richText's `content` is a RichTextValue: a plain string OR a Lexical `{ root }` document. Both are\n    // EDITOR-CONTROLLED and NOT sanitised at write time (the WebDesk API validates shape only), so this\n    // renderer makes them inert here. A string is sanitised via the one route gaiada_sanitize_html()\n    // (wp_kses_post() inside WordPress, htmlspecialchars() outside); a `{ root }` document is embedded as\n    // an inert JSON payload via gaiada_safe_json_for_script(), exactly as RichText.astro does (M6-P5c).\n    $content = $props['content'] ?? null;\n    $body = '';\n    if (is_string($content)) {\n        $body = gaiada_sanitize_html($content);\n    } elseif (is_array($content) && array_key_exists('root', $content)) {\n        $body = gaiada_json_payload($content);\n    }\n    return \"<div class=\\\"gaiada-block gaiada-block-richtext\\\">{$body}</div>\";\n}\n\n/** @param array<string,mixed> $props */\nfunction gaiada_render_block_gallery(array $props): string\n{\n    $items = is_array($props['items'] ?? null) ? $props['items'] : [];\n    $html = '<div class=\"gaiada-block gaiada-block-gallery\">';\n    foreach ($items as $item) {\n        $html .= gaiada_media_img($item);\n    }\n    if (is_string($props['caption'] ?? null) && $props['caption'] !== '') {\n        $html .= '<p class=\"gaiada-gallery-caption\">' . gaiada_h($props['caption']) . '</p>';\n    }\n    return $html . '</div>';\n}\n\n/** @param array<string,mixed> $props */\nfunction gaiada_render_block_cta(array $props): string\n{\n    $heading = gaiada_h($props['heading'] ?? '');\n    $label = gaiada_h($props['buttonLabel'] ?? '');\n    $href = gaiada_h(gaiada_safe_href($props['buttonHref'] ?? '#'));\n    $html = \"<div class=\\\"gaiada-block gaiada-block-cta\\\"><h2>{$heading}</h2>\";\n    if (is_string($props['body'] ?? null) && $props['body'] !== '') {\n        $html .= '<p>' . gaiada_h($props['body']) . '</p>';\n    }\n    return $html . \"<a href=\\\"{$href}\\\">{$label}</a></div>\";\n}\n\n/** One vocabulary `relation` value ({ collection, slug }) as a list item carrying the pointer, as\n *  FeatureGrid.astro / Faq.astro render it: the slug is the visible text. */\nfunction gaiada_relation_item(mixed $rel, string $class): string\n{\n    $r = is_array($rel) ? $rel : [];\n    $collection = gaiada_h($r['collection'] ?? '');\n    $slug = gaiada_h($r['slug'] ?? '');\n    return \"<li class=\\\"{$class}\\\" data-relation-collection=\\\"{$collection}\\\" data-relation-slug=\\\"{$slug}\\\">{$slug}</li>\";\n}\n\n/** @param array<string,mixed> $props */\nfunction gaiada_render_block_featureGrid(array $props): string\n{\n    $items = is_array($props['items'] ?? null) ? $props['items'] : [];\n    $html = '<div class=\"gaiada-block gaiada-block-featuregrid\">';\n    if (is_string($props['heading'] ?? null) && $props['heading'] !== '') {\n        $html .= '<h2>' . gaiada_h($props['heading']) . '</h2>';\n    }\n    $html .= '<ul>';\n    foreach ($items as $item) {\n        $html .= gaiada_relation_item($item, 'gaiada-feature');\n    }\n    return $html . '</ul></div>';\n}\n\n/** @param array<string,mixed> $props */\nfunction gaiada_render_block_form(array $props): string\n{\n    // `formKey` is a relation value { collection, slug } (FormBlock.astro); the slug is the form id.\n    $key = is_array($props['formKey'] ?? null) ? $props['formKey'] : [];\n    $collection = gaiada_h($key['collection'] ?? '');\n    $slug = gaiada_h($key['slug'] ?? '');\n    return \"<div class=\\\"gaiada-block gaiada-block-form\\\" data-gaiada-form-collection=\\\"{$collection}\\\" data-gaiada-form-id=\\\"{$slug}\\\"></div>\";\n}\n\n/** @param array<string,mixed> $props */\nfunction gaiada_render_block_testimonial(array $props): string\n{\n    // `quote` is a richtext value. Testimonial.astro renders a string as escaped text and anything else\n    // as an inert JSON payload; mirrored here.\n    $quote = $props['quote'] ?? '';\n    $quoteHtml = is_string($quote) ? gaiada_h($quote) : gaiada_json_payload($quote);\n    $author = gaiada_h($props['author'] ?? '');\n    $html = \"<blockquote class=\\\"gaiada-block gaiada-block-testimonial\\\">{$quoteHtml}<footer>\";\n    if (gaiada_has_media($props['avatar'] ?? null)) {\n        $html .= gaiada_media_img($props['avatar']);\n    }\n    $html .= \"<cite>{$author}</cite>\";\n    if (is_string($props['role'] ?? null) && $props['role'] !== '') {\n        $html .= '<span class=\"gaiada-testimonial-role\">' . gaiada_h($props['role']) . '</span>';\n    }\n    return $html . '</footer></blockquote>';\n}\n\n/** @param array<string,mixed> $props */\nfunction gaiada_render_block_faq(array $props): string\n{\n    // `items` are relation pointers ({ collection, slug }) to the `faqItem` collection, rendered as\n    // pointers (Faq.astro); there is no inline question/answer in the vocabulary.\n    $items = is_array($props['items'] ?? null) ? $props['items'] : [];\n    $html = '<div class=\"gaiada-block gaiada-block-faq\">';\n    if (is_string($props['heading'] ?? null) && $props['heading'] !== '') {\n        $html .= '<h2>' . gaiada_h($props['heading']) . '</h2>';\n    }\n    $html .= '<ul>';\n    foreach ($items as $item) {\n        $html .= gaiada_relation_item($item, 'gaiada-faq-item');\n    }\n    return $html . '</ul></div>';\n}\n\n/** @param array<string,mixed> $props */\nfunction gaiada_render_block_logoCloud(array $props): string\n{\n    $logos = is_array($props['logos'] ?? null) ? $props['logos'] : [];\n    $html = '<div class=\"gaiada-block gaiada-block-logocloud\">';\n    if (is_string($props['heading'] ?? null) && $props['heading'] !== '') {\n        $html .= '<h2>' . gaiada_h($props['heading']) . '</h2>';\n    }\n    foreach ($logos as $logo) {\n        $html .= gaiada_media_img($logo);\n    }\n    return $html . '</div>';\n}\n\n/** The composition-typed `fields` block (vocabulary 1.1.0, WSK-64). It carries an item's typed field\n *  values for the site's own code to read; it is data, not presentation, so it draws NOTHING and is\n *  not an unknown block (nothing is reported). Mirrors webdesk/blocks/src/renderer: resolve-blocks.ts\n *  treats `fields` as known but non-visual (NON_VISUAL_BLOCK_TYPES) and BlockRenderer.astro returns null\n *  for it. Without this function the dispatcher in block-renderer.php would throw for it, because\n *  `fields` is in gaiada_known_block_types().\n *\n * @param array<string,mixed> $props\n */\nfunction gaiada_render_block_fields(array $props): string\n{\n    return '';\n}\n",
  "inc/block-vocabulary.php": "<?php\n// VENDORED — copied from webdesk/delivery/vocabulary/blocks.ts's BLOCK_TYPE_NAMES (WSK-06/\n// WSK-14, frozen per webdesk-design.md §05). DO NOT HAND-EDIT.\n//\n// PHP cannot import a TypeScript module, so this is a vendored copy of the NAME LIST only\n// (never a restatement of validation rules — those stay TS-side, WSK-06/14's job) — same\n// vendor-with-a-drift-check pattern webdesk/blocks (WSK-16) already established for its own\n// language-boundary problem. Regenerate with `node scripts/vendor-block-vocabulary.mjs` from\n// webdesk/wordpress/. Check for drift with `node scripts/vendor-block-vocabulary.mjs --check`.\ndeclare(strict_types=1);\n\nnamespace GaiadaWebDesk\\Theme;\n\n/** @return string[] */\nfunction gaiada_known_block_types(): array\n{\n    return [\n    'hero',\n    'richText',\n    'gallery',\n    'cta',\n    'featureGrid',\n    'form',\n    'testimonial',\n    'faq',\n    'logoCloud',\n    'fields',\n    ];\n}\n",
  "inc/config.php": "<?php\n// webdesk/wordpress/theme/gaiada-webdesk/inc/config.php\n//\n// M6-P5a — theme configuration. Pure PHP, no WordPress dependency (testable with php-cli alone).\n//\n// RULE: configuration never lives in the WordPress database. Every value comes from a\n// `wp-config.php` constant, falling back to the process environment (`getenv()`). This theme makes no\n// call into the WordPress options API at all, and has no settings form that writes anything.\n//\n//   GAIADA_WEBDESK_BASE_URL   required  e.g. https://api.erp.gaiada.com   (http/https only)\n//   GAIADA_WEBDESK_TENANT     required  the tenant slug the vendored SDK was generated for\n//   GAIADA_WEBDESK_API_KEY    required  never displayed, logged or echoed by this theme\n//   GAIADA_WEBDESK_LOCALES    optional  \"en,id\" (or a PHP array); the FIRST is the default locale\n//   GAIADA_WEBDESK_ROUTES     optional  JSON route map overriding the default (see below)\ndeclare(strict_types=1);\n\nnamespace GaiadaWebDesk\\Theme;\n\nfinal class Config\n{\n    public const REQUIRED = ['GAIADA_WEBDESK_BASE_URL', 'GAIADA_WEBDESK_TENANT', 'GAIADA_WEBDESK_API_KEY'];\n\n    /** @var array<string,string> name => problem (\"missing\" | \"invalid\") */\n    private array $problems = [];\n    private string $baseUrl = '';\n    private string $tenant = '';\n    private string $apiKey = '';\n    /** @var string[] */\n    private array $locales = [];\n    /** @var array<int,array{pattern:string,collection:string,slug:?string}> */\n    private array $routes = [];\n\n    /**\n     * @param array<string,mixed> $values name => raw value (constant or env); absent/empty = unset\n     */\n    public static function fromValues(array $values): self\n    {\n        $c = new self();\n\n        foreach (self::REQUIRED as $name) {\n            $v = $values[$name] ?? null;\n            if (!is_string($v) || trim($v) === '') {\n                $c->problems[$name] = 'missing';\n            }\n        }\n\n        $base = $values['GAIADA_WEBDESK_BASE_URL'] ?? null;\n        if (is_string($base) && trim($base) !== '') {\n            $base = trim($base);\n            $scheme = strtolower((string) parse_url($base, PHP_URL_SCHEME));\n            if (($scheme === 'http' || $scheme === 'https') && parse_url($base, PHP_URL_HOST)) {\n                $c->baseUrl = rtrim($base, '/');\n            } else {\n                $c->problems['GAIADA_WEBDESK_BASE_URL'] = 'invalid';\n            }\n        }\n        $tenant = $values['GAIADA_WEBDESK_TENANT'] ?? null;\n        if (is_string($tenant) && trim($tenant) !== '') {\n            $tenant = trim($tenant);\n            if (preg_match('/^[A-Za-z0-9][A-Za-z0-9_-]*$/', $tenant) === 1) {\n                $c->tenant = $tenant;\n            } else {\n                $c->problems['GAIADA_WEBDESK_TENANT'] = 'invalid';\n            }\n        }\n        $key = $values['GAIADA_WEBDESK_API_KEY'] ?? null;\n        if (is_string($key) && trim($key) !== '') {\n            $c->apiKey = trim($key);\n        }\n\n        $c->locales = self::parseLocales($values['GAIADA_WEBDESK_LOCALES'] ?? null, $c->problems);\n        $c->routes = self::parseRoutes($values['GAIADA_WEBDESK_ROUTES'] ?? null, $c->problems);\n        return $c;\n    }\n\n    /** Reads wp-config.php constants first, then getenv(). */\n    public static function fromEnvironment(): self\n    {\n        $names = array_merge(self::REQUIRED, ['GAIADA_WEBDESK_LOCALES', 'GAIADA_WEBDESK_ROUTES']);\n        $values = [];\n        foreach ($names as $name) {\n            $v = defined($name) ? constant($name) : null;\n            if ($v === null || $v === '' || $v === []) {\n                $env = getenv($name);\n                $v = $env === false ? null : $env;\n            }\n            $values[$name] = $v;\n        }\n        return self::fromValues($values);\n    }\n\n    /**\n     * @param array<string,string> $problems\n     * @return string[]\n     */\n    private static function parseLocales(mixed $raw, array &$problems): array\n    {\n        if ($raw === null || $raw === '' || $raw === []) {\n            return [];\n        }\n        $list = is_array($raw) ? $raw : explode(',', (string) $raw);\n        $out = [];\n        foreach ($list as $item) {\n            $item = is_string($item) ? trim($item) : '';\n            if ($item === '') {\n                continue;\n            }\n            if (preg_match('/^[A-Za-z]{2,3}([_-][A-Za-z0-9]{2,8})*$/', $item) !== 1) {\n                $problems['GAIADA_WEBDESK_LOCALES'] = 'invalid';\n                return [];\n            }\n            if (!in_array($item, $out, true)) {\n                $out[] = $item;\n            }\n        }\n        return $out;\n    }\n\n    /**\n     * Route map: a JSON list of {\"pattern\": \"/blog/{slug}\", \"collection\": \"article\"}, or a fixed\n     * item {\"pattern\": \"/\", \"collection\": \"pages\", \"slug\": \"home\"}. Patterns are literal segments\n     * plus at most one `{slug}` segment. The first match wins; a supplied map REPLACES the default.\n     *\n     * @param array<string,string> $problems\n     * @return array<int,array{pattern:string,collection:string,slug:?string}>\n     */\n    private static function parseRoutes(mixed $raw, array &$problems): array\n    {\n        if ($raw === null || $raw === '' || $raw === []) {\n            return self::defaultRoutes();\n        }\n        $decoded = is_array($raw) ? $raw : json_decode((string) $raw, true);\n        if (!is_array($decoded) || $decoded === [] || array_keys($decoded) !== range(0, count($decoded) - 1)) {\n            $problems['GAIADA_WEBDESK_ROUTES'] = 'invalid';\n            return self::defaultRoutes();\n        }\n        $routes = [];\n        foreach ($decoded as $r) {\n            $pattern = is_array($r) ? ($r['pattern'] ?? null) : null;\n            $collection = is_array($r) ? ($r['collection'] ?? null) : null;\n            $slug = is_array($r) && array_key_exists('slug', $r) ? $r['slug'] : null;\n            $ok = is_string($pattern) && str_starts_with($pattern, '/')\n                && is_string($collection) && preg_match('/^[A-Za-z][A-Za-z0-9]*$/', $collection) === 1\n                && ($slug === null || (is_string($slug) && preg_match('/^[A-Za-z0-9][A-Za-z0-9._-]*$/', $slug) === 1));\n            $segments = [];\n            if ($ok) {\n                $segments = array_values(array_filter(explode('/', $pattern), static fn ($s) => $s !== ''));\n                $slots = count(array_filter($segments, static fn ($s) => $s === '{slug}'));\n                foreach ($segments as $s) {\n                    if ($s !== '{slug}' && preg_match('/^[A-Za-z0-9][A-Za-z0-9._-]*$/', $s) !== 1) {\n                        $ok = false;\n                    }\n                }\n                // exactly one source for the slug: a `{slug}` segment XOR a fixed \"slug\".\n                $ok = $ok && (($slots === 1 && $slug === null) || ($slots === 0 && $slug !== null));\n            }\n            if (!$ok) {\n                $problems['GAIADA_WEBDESK_ROUTES'] = 'invalid';\n                return self::defaultRoutes();\n            }\n            $routes[] = ['pattern' => '/' . implode('/', $segments), 'collection' => $collection, 'slug' => $slug];\n        }\n        return $routes;\n    }\n\n    /** @return array<int,array{pattern:string,collection:string,slug:?string}> */\n    public static function defaultRoutes(): array\n    {\n        return [\n            ['pattern' => '/', 'collection' => 'pages', 'slug' => 'home'],\n            ['pattern' => '/{slug}', 'collection' => 'pages', 'slug' => null],\n        ];\n    }\n\n    /** @return array<string,string> setting NAME => \"missing\"|\"invalid\" — never values */\n    public function problems(): array\n    {\n        return $this->problems;\n    }\n\n    public function isConfigured(): bool\n    {\n        return $this->problems === [];\n    }\n\n    public function baseUrl(): string\n    {\n        return $this->baseUrl;\n    }\n\n    public function tenant(): string\n    {\n        return $this->tenant;\n    }\n\n    public function apiKey(): string\n    {\n        return $this->apiKey;\n    }\n\n    public function hasApiKey(): bool\n    {\n        return $this->apiKey !== '';\n    }\n\n    /** @return string[] */\n    public function locales(): array\n    {\n        return $this->locales;\n    }\n\n    public function defaultLocale(): ?string\n    {\n        return $this->locales[0] ?? null;\n    }\n\n    /** @return array<int,array{pattern:string,collection:string,slug:?string}> */\n    public function routes(): array\n    {\n        return $this->routes;\n    }\n}\n",
  "inc/layout.php": "<?php\n// webdesk/wordpress/theme/gaiada-webdesk/inc/layout.php\n//\n// M6-P5a — the one HTML document wrapper. Pure PHP, no WordPress dependency: the WordPress glue\n// (functions.php) passes in whatever wp_head()/wp_footer() printed; everything else is escaped here.\ndeclare(strict_types=1);\n\nnamespace GaiadaWebDesk\\Theme;\n\n/**\n * @param string $head   trusted markup from wp_head() (empty outside WordPress)\n * @param string $footer trusted markup from wp_footer() (empty outside WordPress)\n */\nfunction gaiada_webdesk_document(string $title, string $body, string $lang = 'en', string $head = '', string $footer = ''): string\n{\n    $t = htmlspecialchars($title, ENT_QUOTES, 'UTF-8');\n    $l = htmlspecialchars($lang !== '' ? $lang : 'en', ENT_QUOTES, 'UTF-8');\n    return \"<!doctype html>\\n<html lang=\\\"{$l}\\\">\\n<head>\\n<meta charset=\\\"utf-8\\\">\\n\"\n        . \"<meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1\\\">\\n\"\n        . \"<title>{$t}</title>\\n{$head}\\n</head>\\n<body>\\n<main class=\\\"gaiada-webdesk\\\">\\n{$body}\\n</main>\\n{$footer}\\n</body>\\n</html>\\n\";\n}\n",
  "inc/router.php": "<?php\n// webdesk/wordpress/theme/gaiada-webdesk/inc/router.php\n//\n// M6-P5a — request routing for the headless theme. A plain PHP class with NO WordPress dependency,\n// so every outcome can be proven with php-cli alone (test/router-probe.php). WordPress glue\n// (functions.php) is thin: one `template_redirect` hook hands the request path to Router::handle().\n//\n// Default route map: `/` -> collection \"pages\", slug \"home\"; `/{slug}/` -> collection \"pages\",\n// slug {slug}. An optional locale prefix (`/id/...`) is active only when GAIADA_WEBDESK_LOCALES is\n// set; any listed locale (the default one included) is accepted as a prefix, and an unprefixed\n// path means the FIRST (default) locale. GAIADA_WEBDESK_ROUTES replaces the map (see config.php).\n//\n// Outcomes: 200 rendered blocks · 404 no route / item absent / collection absent from the SDK ·\n// 502 /v1 errored or timed out · 503 not configured · 405 non-GET/HEAD · 500 theme bug while\n// rendering. Never echoes the API key or an upstream error body — the 502 page is static text.\ndeclare(strict_types=1);\n\nnamespace GaiadaWebDesk\\Theme;\n\nrequire_once __DIR__ . '/config.php';\nrequire_once __DIR__ . '/layout.php';\nrequire_once __DIR__ . '/block-renderer.php';\n\n/** The item does not exist (or the tenant has no such collection). */\nfinal class ItemNotFound extends \\RuntimeException\n{\n}\n\n/** /v1 errored, timed out or was unreachable. Carry no upstream body. */\nfinal class UpstreamUnavailable extends \\RuntimeException\n{\n}\n\nfinal class Router\n{\n    private Config $config;\n    /** @var callable(string,string,?string):array<string,mixed> */\n    private $fetch;\n    /** @var callable(string):void */\n    private $log;\n    /** @var array<string,array<string,mixed>> per-request memo, keyed collection|slug|locale */\n    private array $memo = [];\n\n    /**\n     * @param callable(string $collection, string $slug, ?string $locale): array<string,mixed> $fetch\n     *        returns an ItemEnvelope; throws ItemNotFound or UpstreamUnavailable\n     * @param (callable(string):void)|null $log defaults to error_log\n     */\n    public function __construct(Config $config, callable $fetch, ?callable $log = null)\n    {\n        $this->config = $config;\n        $this->fetch = $fetch;\n        $this->log = $log ?? static function (string $m): void {\n            error_log($m);\n        };\n    }\n\n    /**\n     * @return array{collection:string,slug:string,locale:?string}|null\n     */\n    public function match(string $path): ?array\n    {\n        $q = strcspn($path, '?#');\n        $path = substr($path, 0, $q);\n        $segments = $path === '' ? [] : explode('/', trim($path, '/'));\n        if ($segments === [''] ) {\n            $segments = [];\n        }\n        $clean = [];\n        foreach ($segments as $s) {\n            $s = rawurldecode($s);\n            if (preg_match('/^[A-Za-z0-9][A-Za-z0-9._-]*$/', $s) !== 1) {\n                return null; // empty, dot-leading, or any unexpected character: never reaches /v1\n            }\n            $clean[] = $s;\n        }\n\n        $locale = $this->config->defaultLocale();\n        if ($this->config->locales() !== [] && $clean !== [] && in_array($clean[0], $this->config->locales(), true)) {\n            $locale = $clean[0];\n            array_shift($clean);\n        }\n\n        foreach ($this->config->routes() as $route) {\n            $pattern = array_values(array_filter(explode('/', $route['pattern']), static fn ($s) => $s !== ''));\n            if (count($pattern) !== count($clean)) {\n                continue;\n            }\n            $slug = $route['slug'];\n            $hit = true;\n            foreach ($pattern as $i => $seg) {\n                if ($seg === '{slug}') {\n                    $slug = $clean[$i];\n                } elseif ($seg !== $clean[$i]) {\n                    $hit = false;\n                    break;\n                }\n            }\n            if ($hit && $slug !== null) {\n                return ['collection' => $route['collection'], 'slug' => $slug, 'locale' => $locale];\n            }\n        }\n        return null;\n    }\n\n    /**\n     * @return array{status:int,title:string,body:string,headers:array<string,string>,lang:string}\n     */\n    public function handle(string $method, string $path): array\n    {\n        $method = strtoupper($method);\n        if ($method !== 'GET' && $method !== 'HEAD') {\n            return $this->page(405, 'Method not allowed', '<h1>Method not allowed</h1>', ['Allow' => 'GET, HEAD']);\n        }\n        if (!$this->config->isConfigured()) {\n            $names = '';\n            foreach ($this->config->problems() as $name => $why) {\n                $names .= '<li><code>' . $this->e($name) . '</code> (' . $this->e($why) . ')</li>';\n            }\n            return $this->page(\n                503,\n                'WebDesk is not configured',\n                '<h1>WebDesk is not configured</h1><p>This site renders from WebDesk and cannot show content until '\n                . 'these settings are provided in <code>wp-config.php</code> or the environment:</p><ul>' . $names . '</ul>',\n                ['Retry-After' => '300'],\n            );\n        }\n\n        $route = $this->match($path);\n        if ($route === null) {\n            return $this->notFound();\n        }\n\n        try {\n            $item = $this->item($route['collection'], $route['slug'], $route['locale']);\n        } catch (ItemNotFound) {\n            return $this->notFound();\n        } catch (\\Throwable $e) {\n            // Class name only — never the message, which may carry upstream detail.\n            ($this->log)('[gaiada-webdesk] /v1 request failed (' . get_class($e) . ') for ' . $route['collection'] . '/' . $route['slug']);\n            return $this->page(\n                502,\n                'Content temporarily unavailable',\n                '<h1>Content temporarily unavailable</h1><p>This page could not be loaded right now. Please try again shortly.</p>',\n            );\n        }\n\n        try {\n            $blocks = is_array($item['blocks'] ?? null) ? $item['blocks'] : [];\n            $body = '';\n            if (!empty($item['meta']['draft'])) {\n                $body .= '<div class=\"gaiada-draft-banner\">Draft preview</div>';\n            }\n            $body .= gaiada_render_blocks($blocks, $route['collection'], $route['slug']);\n        } catch (\\Throwable $e) {\n            ($this->log)('[gaiada-webdesk] render failed (' . get_class($e) . ') for ' . $route['collection'] . '/' . $route['slug']);\n            return $this->page(500, 'Something went wrong', '<h1>Something went wrong</h1>');\n        }\n\n        $seoTitle = is_array($item['seo'] ?? null) && is_string($item['seo']['title'] ?? null) ? $item['seo']['title'] : '';\n        $title = $seoTitle !== '' ? $seoTitle : $route['slug'];\n        $lang = $route['locale'] ?? (is_string($item['locale'] ?? null) ? $item['locale'] : 'en');\n        return ['status' => 200, 'title' => $title, 'body' => $body, 'headers' => [], 'lang' => $lang];\n    }\n\n    /** @return array<string,mixed> */\n    private function item(string $collection, string $slug, ?string $locale): array\n    {\n        $key = $collection . '|' . $slug . '|' . ($locale ?? '');\n        return $this->memo[$key] ??= ($this->fetch)($collection, $slug, $locale);\n    }\n\n    /** @return array{status:int,title:string,body:string,headers:array<string,string>,lang:string} */\n    private function notFound(): array\n    {\n        return $this->page(404, 'Page not found', '<h1>Page not found</h1><p>There is nothing at this address.</p>');\n    }\n\n    /**\n     * @param array<string,string> $headers\n     * @return array{status:int,title:string,body:string,headers:array<string,string>,lang:string}\n     */\n    private function page(int $status, string $title, string $body, array $headers = []): array\n    {\n        return ['status' => $status, 'title' => $title, 'body' => $body, 'headers' => $headers, 'lang' => $this->config->defaultLocale() ?? 'en'];\n    }\n\n    private function e(string $s): string\n    {\n        return htmlspecialchars($s, ENT_QUOTES, 'UTF-8');\n    }\n}\n",
  "inc/safety.php": "<?php\n// webdesk/wordpress/theme/gaiada-webdesk/inc/safety.php\n//\n// M6-P5c — render-time output safety for the PHP theme (stored-XSS class), mirroring\n// webdesk/blocks/src/safety.ts (the Astro half). Client editors can edit their own site's content\n// (rulings WSK-D58–D60), so every editor-controlled value that reaches an href/src, an inline\n// <script type=\"application/json\"> or raw HTML is made inert HERE. The WebDesk API validates SHAPE\n// only (richtext = a string or a `{ root }` object, markdown = a string); it does not sanitise\n// content at write time, so this renderer must not assume anything did.\n//\n//   gaiada_safe_href(v)          link allow-list; anything else -> '#'\n//   gaiada_safe_img_src(v)       image src allow-list; anything else -> '' (caller omits the attribute)\n//   gaiada_safe_json_for_script  JSON for a <script type=\"application/json\"> body, cannot close the tag\n//   gaiada_sanitize_html(s)      wp_kses_post() inside WordPress, htmlspecialchars() outside it\ndeclare(strict_types=1);\n\nnamespace GaiadaWebDesk\\Theme;\n\n/**\n * Shared URL check. Browsers ignore leading/trailing C0 controls and spaces and strip tab/LF/CR\n * anywhere in a URL before reading its scheme, so every ASCII control character and space is\n * removed for the CHECK (\"java\\tscript:\", \" javascript:\", \"JaVaScRiPt:\" all resolve to the same\n * scheme). Returns the value to emit (trimmed, control characters removed) or null when refused.\n *\n * @param string[] $allowedSchemes lower-case, with the trailing colon\n */\nfunction gaiada_check_url(mixed $value, array $allowedSchemes, bool $allowFragmentAndQuery): ?string\n{\n    if (!is_string($value)) {\n        return null;\n    }\n    $cleaned = preg_replace('/[\\x00-\\x20\\x7f]+/', '', $value);\n    if (!is_string($cleaned) || $cleaned === '') {\n        return null;\n    }\n    if (preg_match('/^[a-z][a-z0-9+.-]*:/i', $cleaned, $m) === 1) {\n        if (!in_array(strtolower($m[0]), $allowedSchemes, true)) {\n            return null;\n        }\n    } elseif ($cleaned[0] === '/') {\n        // \"//host\" and \"/\\host\" are scheme-relative (browsers treat \"\\\" as \"/\"): not a local path.\n        if (isset($cleaned[1]) && ($cleaned[1] === '/' || $cleaned[1] === '\\\\')) {\n            return null;\n        }\n    } elseif ($cleaned[0] === '?' || $cleaned[0] === '#') {\n        if (!$allowFragmentAndQuery) {\n            return null;\n        }\n    } elseif (preg_match('~^[^\\\\\\\\:/?#]+(?:[/?#][^\\\\\\\\]*)?$~', $cleaned) !== 1) {\n        // A relative path (\"about/\", \"page.html\", \"./x\", \"../x\"): no backslash anywhere (browsers\n        // read a backslash as \"/\", so two of them would be scheme-relative) and no \":\" before the\n        // first \"/\", \"?\" or \"#\". (In this single-quoted PHP string \"\\\\\\\\\" is one regex-escaped backslash.)\n        return null;\n    }\n    $out = preg_replace('/[\\x00-\\x1f\\x7f]+/', '', $value);\n    return is_string($out) ? trim($out) : null;\n}\n\n/** href allow-list: http, https, mailto, tel, \"/x\", relative paths (\"x\", \"./x\", \"../x\"), \"?x\", \"#x\". Anything else is \"#\". */\nfunction gaiada_safe_href(mixed $value): string\n{\n    return gaiada_check_url($value, ['http:', 'https:', 'mailto:', 'tel:'], true) ?? '#';\n}\n\n/** img src allow-list: http, https, \"/x\", relative paths. Anything else is '' (omit the attribute). */\nfunction gaiada_safe_img_src(mixed $value): string\n{\n    return gaiada_check_url($value, ['http:', 'https:'], false) ?? '';\n}\n\n/** json_encode for the body of a <script type=\"application/json\">: `<`, `>`, `&`, U+2028 and U+2029\n *  become \\uXXXX escapes, so content can never close the tag or open a comment. Still valid JSON. */\nfunction gaiada_safe_json_for_script(mixed $value): string\n{\n    $json = json_encode($value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);\n    if (!is_string($json)) {\n        return 'null';\n    }\n    return strtr($json, [\n        '<' => '\\u003c',\n        '>' => '\\u003e',\n        '&' => '\\u0026',\n        \"\\u{2028}\" => '\\u2028',\n        \"\\u{2029}\" => '\\u2029',\n    ]);\n}\n\n/** The ONE route for editor-controlled HTML (richText). Inside WordPress it is wp_kses_post(); outside\n *  WordPress (php-cli probes, a host without WP loaded) it is htmlspecialchars(), so the fallback is\n *  always safe and never \"allow\". */\nfunction gaiada_sanitize_html(string $html): string\n{\n    if (function_exists('wp_kses_post')) {\n        return (string) \\wp_kses_post($html);\n    }\n    return htmlspecialchars($html, ENT_QUOTES, 'UTF-8');\n}\n",
  "inc/sdk-transport.php": "<?php\n// webdesk/wordpress/theme/gaiada-webdesk/inc/sdk-transport.php\n//\n// M6-P5a — the production transport behind Router: adapts the GENERATED PHP SDK\n// (vendor/gaiada-sdk/sdk.php, WSK-34) to the Router's fetch contract. No WordPress dependency.\n//\n// URL shapes are the SDK's own, never built here: `get<Collection>($slug, ['locale' => ...])` ->\n// GET /v1/t/{tenant}/{collection}/{slug}?locale=..., and `sitemapXml()` -> GET /v1/t/{tenant}/sitemap.xml\n// (used only by the settings page's \"Test connection\"). No retries, no caching: the SDK makes one\n// curl call (its own 10 s timeout) and this adapter makes exactly one SDK call per request.\ndeclare(strict_types=1);\n\nnamespace GaiadaWebDesk\\Theme;\n\nrequire_once __DIR__ . '/config.php';\nrequire_once __DIR__ . '/router.php';\nrequire_once __DIR__ . '/../vendor/gaiada-sdk/sdk.php';\n\nuse GaiadaWebDesk\\Sdk\\WebDeskApiException;\nuse GaiadaWebDesk\\Sdk\\WebDeskClient;\n\n/**\n * @return callable(string,string,?string):array<string,mixed>\n */\nfunction gaiada_webdesk_sdk_fetcher(Config $config): callable\n{\n    $client = new WebDeskClient($config->baseUrl(), $config->apiKey());\n    return static function (string $collection, string $slug, ?string $locale) use ($client): array {\n        $method = 'get' . ucfirst($collection);\n        if (!is_callable([$client, $method])) {\n            // The tenant's contract has no such collection: nothing to render at this address.\n            throw new ItemNotFound('collection not in this tenant\\'s SDK');\n        }\n        try {\n            return $client->{$method}($slug, $locale !== null ? ['locale' => $locale] : []);\n        } catch (WebDeskApiException $e) {\n            if ($e->status === 404) {\n                throw new ItemNotFound('item not found');\n            }\n            throw new UpstreamUnavailable('upstream status ' . $e->status);\n        } catch (\\RuntimeException $e) {\n            throw new UpstreamUnavailable('transport failure'); // curl error text is deliberately dropped\n        }\n    };\n}\n\n/**\n * One /v1 call for the settings page. Reports a status code or \"no response\" — never a body,\n * never the key.\n *\n * @return array{ok:bool,status:?int,message:string}\n */\nfunction gaiada_webdesk_test_connection(Config $config): array\n{\n    if (!$config->isConfigured()) {\n        return ['ok' => false, 'status' => null, 'message' => 'Not configured.'];\n    }\n    $client = new WebDeskClient($config->baseUrl(), $config->apiKey());\n    try {\n        $client->sitemapXml($config->defaultLocale() !== null ? ['locale' => $config->defaultLocale()] : []);\n        return ['ok' => true, 'status' => 200, 'message' => 'HTTP 200'];\n    } catch (WebDeskApiException $e) {\n        return ['ok' => false, 'status' => $e->status, 'message' => 'HTTP ' . $e->status];\n    } catch (\\Throwable $e) {\n        return ['ok' => false, 'status' => null, 'message' => 'No response (network error or timeout).'];\n    }\n}\n",
  "inc/settings-page.php": "<?php\n// webdesk/wordpress/theme/gaiada-webdesk/inc/settings-page.php\n//\n// M6-P5a — Settings -> WebDesk. READ-ONLY: it shows what wp-config.php / the environment say and\n// can run one \"Test connection\" call. It registers no setting, saves no option and writes nothing\n// to the database (the test result is rendered in the same response, not stored). The key is never\n// displayed — only whether one is present. Needs WordPress (admin hooks); loaded only from\n// functions.php, never by the php-cli probes.\ndeclare(strict_types=1);\n\nnamespace GaiadaWebDesk\\Theme;\n\nrequire_once __DIR__ . '/config.php';\nrequire_once __DIR__ . '/sdk-transport.php';\n\nadd_action('admin_menu', static function (): void {\n    add_options_page('WebDesk', 'WebDesk', 'manage_options', 'gaiada-webdesk', __NAMESPACE__ . '\\\\gaiada_webdesk_render_settings_page');\n});\n\nfunction gaiada_webdesk_render_settings_page(): void\n{\n    if (!current_user_can('manage_options')) {\n        wp_die(esc_html__('You do not have permission to view this page.'), '', ['response' => 403]);\n    }\n    $config = Config::fromEnvironment();\n\n    $result = null;\n    if (($_SERVER['REQUEST_METHOD'] ?? '') === 'POST' && isset($_POST['gaiada_webdesk_test'])) {\n        check_admin_referer('gaiada_webdesk_test_connection'); // nonce; dies on failure\n        if (!current_user_can('manage_options')) {\n            wp_die(esc_html__('You do not have permission to do that.'), '', ['response' => 403]);\n        }\n        $result = gaiada_webdesk_test_connection($config);\n    }\n\n    $rows = [\n        'Base URL' => $config->baseUrl() !== '' ? $config->baseUrl() : '(not set)',\n        'Tenant' => $config->tenant() !== '' ? $config->tenant() : '(not set)',\n        'Locales' => $config->locales() !== [] ? implode(', ', $config->locales()) . ' (default: ' . $config->defaultLocale() . ')' : '(none: single locale)',\n        'API key' => $config->hasApiKey() ? 'present' : 'missing',\n        'Routes' => count($config->routes()) . ' route(s)',\n    ];\n\n    echo '<div class=\"wrap\"><h1>WebDesk</h1>';\n    echo '<p>Read-only. Configure with <code>GAIADA_WEBDESK_*</code> constants in <code>wp-config.php</code> or environment variables; nothing here is stored in the database.</p>';\n    if (!$config->isConfigured()) {\n        echo '<div class=\"notice notice-error\"><p>Not configured. Problems: ';\n        $parts = [];\n        foreach ($config->problems() as $name => $why) {\n            $parts[] = esc_html($name . ' (' . $why . ')');\n        }\n        echo implode(', ', $parts) . '</p></div>';\n    }\n    echo '<table class=\"widefat striped\" style=\"max-width:640px\"><tbody>';\n    foreach ($rows as $label => $value) {\n        echo '<tr><th scope=\"row\">' . esc_html($label) . '</th><td>' . esc_html($value) . '</td></tr>';\n    }\n    echo '</tbody></table>';\n\n    echo '<form method=\"post\" style=\"margin-top:1em\">';\n    wp_nonce_field('gaiada_webdesk_test_connection');\n    echo '<input type=\"hidden\" name=\"gaiada_webdesk_test\" value=\"1\">';\n    submit_button('Test connection', 'secondary', 'submit', false, $config->isConfigured() ? [] : ['disabled' => 'disabled']);\n    echo '</form>';\n\n    if ($result !== null) {\n        $class = $result['ok'] ? 'notice-success' : 'notice-error';\n        echo '<div class=\"notice ' . esc_attr($class) . '\"><p>Test connection: ' . esc_html($result['message']) . '</p></div>';\n    }\n    echo '</div>';\n}\n",
  "index.php": "<?php\n// Required by WordPress for every theme. Never reached in normal operation: functions.php hands\n// every front-end request to the WebDesk router on `template_redirect` and exits. If this file is\n// ever rendered, that hook did not run, so answer honestly rather than showing a blank page.\ndeclare(strict_types=1);\n\nstatus_header(503);\necho '<!doctype html><title>WebDesk theme not active</title><h1>WebDesk theme not active</h1>';\n",
  "style.css": "/*\nTheme Name: Gaiada WebDesk (headless)\nDescription: Headless-consumer theme. Every front-end request renders content fetched from WebDesk's /v1 through the generated PHP SDK (vendor/gaiada-sdk/sdk.php), never WordPress posts or pages. Configure with GAIADA_WEBDESK_* constants in wp-config.php (or environment variables); nothing is stored in the database.\nAuthor: Gaiada\nVersion: 1.0.0\nRequires PHP: 8.1\n*/\n\n.gaiada-draft-banner { background: #fff4ce; padding: 0.5rem 1rem; text-align: center; }\n",
};
